  Object.entries(feedbackUi[i18n?.locale] || {}).forEach(([english, translated]) => uiMap.set(english, translated));
  const ui = (english) => uiMap.get(String(english)) || window.CUACCatalogContent?.text(english) || String(english);
  const page = document.body.dataset.catalogListPage || "";

  function localizeHref(href) {
    if (i18n?.href) return i18n.href(href);
    if (!href || href.startsWith("#") || /^(mailto:|tel:|javascript:)/i.test(href) || !i18n) return href;
    const url = new URL(href, location.href);
    if (url.origin !== location.origin || !(url.pathname.toLowerCase().endsWith(".html") || /^\/(?:guides|insights)(?:\/|$)/.test(url.pathname))) return href;
    url.searchParams.set("lang", i18n.locale);
    return `${url.pathname}${url.search}${url.hash}`;
  }

  function applyLinks(root = document) {
    const anchors = root.matches?.("a[href]") ? [root] : [...(root.querySelectorAll?.("a[href]") || [])];
    anchors.forEach((anchor) => {
      if (anchor.closest?.("[data-catalog-original]")) return;
      const localized = localizeHref(anchor.getAttribute("href"));
      if (localized && localized !== anchor.getAttribute("href")) anchor.setAttribute("href", localized);
    });
  }

  function applyUi(root = document) {
    const targets = root.matches?.("[data-catalog-ui]") ? [root] : [...(root.querySelectorAll?.("[data-catalog-ui]") || [])];
    targets.forEach((target) => { target.textContent = ui(target.textContent.trim()); });
    const placeholders = root.matches?.("[data-catalog-placeholder]") ? [root] : [...(root.querySelectorAll?.("[data-catalog-placeholder]") || [])];
    placeholders.forEach((target) => { target.placeholder = ui(target.placeholder); });
    (root.querySelectorAll?.("[placeholder], [aria-label], [title]") || []).forEach(target => {
      ["placeholder", "aria-label", "title"].forEach(attribute => {
        const value = target.getAttribute(attribute);
        if (value && uiMap.has(value)) target.setAttribute(attribute, ui(value));
      });
    });
  }

  function apply() {
    document.querySelectorAll("[data-catalog-copy]").forEach((target) => {
      target.textContent = t(target.dataset.catalogCopy, target.textContent);
    });
    const pageTitle = t(`${page}.pageTitle`, document.title);
    if (pageTitle) document.title = pageTitle;
    applyUi();
    applyLinks();
  }

  window.CUACCatalogI18n = Object.freeze({ locale: i18n?.locale || "en", t, ui, format, apply, applyUi, applyLinks, localizeHref });
  apply();
  if (i18n) {
    new MutationObserver((records) => records.forEach((record) => record.addedNodes.forEach((node) => {
      if (node.nodeType === Node.ELEMENT_NODE) { applyUi(node); applyLinks(node); }
    }))).observe(document.body, { childList: true, subtree: true });
  }
